callback_with_context.context_function_id:
# get a list of all instances of this particular effect and sum their value #
(effects_list = nodes_list.Transform(EffectList).Filter(EffectKey == effect.EffectKey)) => {
effect.LocalisedTextWithCustomValue(GetIfElse(effects_list.IsEmpty, 0, RoundFloat(effects_list.Sum(Value)))) }
